function randomFrom(arr){return arr[Math.floor(Math.random()*arr.length)];}
function rerollTarget(){meta.targetItem=randomFrom(targetPools[meta.difficulty||'C']);saveMeta();}
if(!meta.difficulty||!difficultyConfig[meta.difficulty])meta.difficulty='C';
