renderLoadout=function(){
 UI.loadoutGrid.innerHTML=slotInfo.map(function(s){const slot=s[0],label=s[1],category=s[2],equipped=meta.equipped[slot],choices=Object.keys(meta.stash).filter(function(id){const d=itemDefs[id];if(!d||stashCount(id)<=0)return false;if(category==='weapon')return d.category==='weapon'&&d.weaponSlot===slot;return d.category===category;}).sort(function(a,b){return gearLevel(a)-gearLevel(b);});let html='<div class="slotCard gearTierCard '+tierClass(equipped)+'"><h3>'+label+'</h3><div class="equipped itemNameTier '+tierClass(equipped)+'">'+(equipped?itemDefs[equipped].icon+' '+itemDefs[equipped].name:'未裝備')+'</div><p>'+(equipped?tierBadge(equipped)+' '+itemStatsText(equipped):(slot==='primary'?'必須配置符合難度的主武器。':'未配置'))+'</p><div class="choiceList">';choices.forEach(function(id){html+='<button class="choiceBtn '+tierClass(id)+' '+(id===equipped?'':'secondary')+'" data-equip="'+id+'" data-category="'+slot+'">'+(id===equipped?'已選擇｜':'裝備｜')+itemDefs[id].name+'｜'+gearLevel(id)+'級 ×'+stashCount(id)+'</button>';});if(equipped)html+='<button class="choiceBtn ghost" data-unequip="'+slot+'">卸下</button>';return html+'</div></div>';}).join('')+
 '<div class="slotCard"><h3>消耗品</h3><div class="equipped">F 醫療／G 手雷</div><p>短按快速使用上次選擇；長按開啟輪盤。成功撤離會返還未使用品。</p><div class="choiceList">'+raidConsumableConfig.map(function(c){const d=itemDefs[c.id],enabled=!!meta[c.flag];return'<button class="choiceBtn '+(enabled?'':'secondary')+'" data-toggle="'+c.flag+'">'+d.name+'：'+(enabled?'帶入':'不帶')+'｜庫存 '+stashCount(c.id)+'</button>';}).join('')+'</div></div>';
};

renderStash=function(){const ids=Object.keys(meta.stash).filter(function(id){return stashCount(id)>0&&itemDefs[id];}).sort(function(a,b){return (gearLevel(b)-gearLevel(a))||itemDefs[a].category.localeCompare(itemDefs[b].category);});UI.stashGrid.innerHTML=ids.length?ids.map(function(id){const d=itemDefs[id],sellable=d.sell>0;return'<div class="stashCard gearTierCard '+tierClass(id)+'"><div class="itemIcon">'+d.icon+'</div><h3 class="itemNameTier '+tierClass(id)+'">'+d.name+' <span class="qty">×'+stashCount(id)+'</span></h3><p>'+tierBadge(id)+' '+itemStatsText(id)+'</p><div class="cardButtons">'+(sellable?'<button class="secondary" data-sell="'+id+'">出售 1 件（'+d.sell+'）</button>':'')+'</div></div>';}).join(''):'<div class="stashCard"><h3>倉庫是空的</h3><p>從商城購買，或成功撤離帶回物品。</p></div>';document.getElementById('sellAllLootBtn').disabled=stashLootValue()<=0;};

renderShop=function(){UI.shopGrid.innerHTML=shopIds.slice().sort(function(a,b){return (gearLevel(a)-gearLevel(b))||(itemDefs[a].buy-itemDefs[b].buy);}).map(function(id){const d=itemDefs[id];return'<div class="shopCard gearTierCard '+tierClass(id)+'"><div class="itemIcon">'+d.icon+'</div><h3 class="itemNameTier '+tierClass(id)+'">'+d.name+'</h3><p>'+d.desc+'</p><div class="tagRow">'+tierBadge(id)+'<span class="tag">'+itemStatsText(id)+'</span><span class="tag">庫存 '+stashCount(id)+'</span></div><div class="price">購買價格 '+d.buy+'</div><button data-buy="'+id+'" '+(meta.credits<d.buy?'disabled':'')+'>購買 1 件</button></div>';}).join('');};

setupLockedRoom=function(){
 currentMap.walls=[{x:0,y:0,w:currentMap.world.w,h:70},{x:0,y:currentMap.world.h-70,w:currentMap.world.w,h:70},{x:0,y:0,w:70,h:currentMap.world.h},{x:currentMap.world.w-70,y:0,w:70,h:currentMap.world.h}];
 currentMap.buildings=[];currentMap.lockedRooms=[];currentMap.chestPositions=[];currentMap.enemyCandidates=[];currentMap.bushes=[];currentMap.treeTrunks=[];currentMap.vehicles=[];currentMap.coverProps=[];currentMap.rocks=[];currentMap.localRoads=[];currentMap.grassPatches=[];currentMap.fences=[];currentMap.streetLights=[];
 const thickness=54,doorWidth=145;
 function addWall(x,y,w,h,buildingIndex,visualKind){if(w>0&&h>0)currentMap.walls.push({x:x,y:y,w:w,h:h,buildingIndex:buildingIndex==null?null:buildingIndex,visualKind:visualKind||null});}
 function rectOverlap(a,b,m){m=m||0;return a.x<a.x+a.w&&a.x<b.x+b.w+m&&a.x+a.w+m>b.x&&a.y<b.y+b.h+m&&a.y+a.h+m>b.y;}
 function inWaterRect(r){return currentMap.waterZones.some(function(z){const cx=Math.max(r.x,Math.min(z.x,r.x+r.w)),cy=Math.max(r.y,Math.min(z.y,r.y+r.h)),dx=(cx-z.x)/z.rx,dy=(cy-z.y)/z.ry;return dx*dx+dy*dy<1.05;});}
 function inRoadRect(r){return currentMap.roads.concat(currentMap.localRoads).some(function(rd){return r.x<rd.x+rd.w+80&&r.x+r.w>rd.x-80&&r.y<rd.y+rd.h+80&&r.y+r.h>rd.y-80;});}
 function canBuild(spec,list){const r={x:spec.x,y:spec.y,w:spec.w,h:spec.h},nearExtraction=extractionPoints().some(function(e){return r.x<e.x+e.w+120&&r.x+r.w+120>e.x&&r.y<e.y+e.h+120&&r.y+r.h+120>e.y;});if(r.x<160||r.y<160||r.x+r.w>currentMap.world.w-160||r.y+r.h>currentMap.world.h-160||inWaterRect(r)||inRoadRect(r)||nearExtraction)return false;return !list.some(function(b){return r.x<b.x+b.w+100&&r.x+r.w+100>b.x&&r.y<b.y+b.h+100&&r.y+r.h+100>b.y;});}
 function addBuilding(spec,index){
   const x=spec.x,y=spec.y,w=spec.w,h=spec.h,side=spec.door||'bottom';
   const building={x:x,y:y,w:w,h:h,locked:!!spec.locked,index:index,doorSide:side,visualHeight:22+(index%3)*7,roofStyle:index%4};
   currentMap.buildings.push(building);let door;
   if(side==='bottom'){const dx=x+w*.5-doorWidth*.5;addWall(x,y,w,thickness,index);addWall(x,y,thickness,h,index);addWall(x+w-thickness,y,thickness,h,index);addWall(x,y+h-thickness,dx-x,thickness,index);addWall(dx+doorWidth,y+h-thickness,x+w-(dx+doorWidth),thickness,index);door={x:dx,y:y+h-thickness,w:doorWidth,h:thickness};}
   else if(side==='top'){const dx=x+w*.5-doorWidth*.5;addWall(x,y,dx-x,thickness,index);addWall(dx+doorWidth,y,x+w-(dx+doorWidth),thickness,index);addWall(x,y,thickness,h,index);addWall(x+w-thickness,y,thickness,h,index);addWall(x,y+h-thickness,w,thickness,index);door={x:dx,y:y,w:doorWidth,h:thickness};}
   else if(side==='left'){const dy=y+h*.5-doorWidth*.5;addWall(x,y,thickness,dy-y,index);addWall(x,dy+doorWidth,thickness,y+h-(dy+doorWidth),index);addWall(x,y,w,thickness,index);addWall(x,y+h-thickness,w,thickness,index);addWall(x+w-thickness,y,thickness,h,index);door={x:x,y:dy,w:thickness,h:doorWidth};}
   else{const dy=y+h*.5-doorWidth*.5;addWall(x+w-thickness,y,thickness,dy-y,index);addWall(x+w-thickness,dy+doorWidth,thickness,y+h-(dy+doorWidth),index);addWall(x,y,w,thickness,index);addWall(x,y+h-thickness,w,thickness,index);addWall(x,y,thickness,h,index);door={x:x+w-thickness,y:dy,w:thickness,h:doorWidth};}
   building.door=door;
   if(w>1000){const px=x+w*.55;addWall(px,y+thickness,thickness,h*.30,index);addWall(px,y+h*.68,thickness,h*.32-thickness,index);}
   if(spec.locked)currentMap.lockedRooms.push({id:'room'+currentMap.lockedRooms.length,name:spec.roomName,keyId:spec.locked,room:{x:x,y:y,w:w,h:h},door:door,unlocked:false,crate:{x:x+w*.68,y:y+h*.48}});
   [[x-170,y+h*.5],[x+w+170,y+h*.5],[x+w*.5,y-170],[x+w*.5,y+h+170],[x+w*.32,y+h*.55]].forEach(function(p){currentMap.enemyCandidates.push(p);});
 }
 const specs=currentMap.buildingSpecs.map(function(x){return clone(x);});
 const anchors={depot:[[1700,2200],[3500,6300],[12100,2200],[12900,6900],[6900,2600]],wetland:[[1800,1700],[2500,4800],[13500,4700],[2500,8300],[10600,8300]],port:[[1900,1800],[2300,3600],[2500,6900],[13200,2200],[13400,6600],[7700,6000]]}[currentMap.id];
 anchors.forEach(function(a,ai){currentMap.localRoads.push({x:a[0]-1550,y:a[1]+220,w:4200,h:220});currentMap.localRoads.push({x:a[0]+680,y:a[1]-1150,w:220,h:3000});const cols=[-1400,-760,1080,1740],rows=[-880,-320,690];rows.forEach(function(ry,ri){cols.forEach(function(cx,ci){const spec={x:a[0]+cx+(ri%2)*55,y:a[1]+ry,w:500+((ai+ci+4)%3)*65,h:385+((ai+ri+3)%3)*50,door:['bottom','right','top','left'][(ai+ri+ci)%4]};if(canBuild(spec,specs))specs.push(spec);});});});
 for(let gy=520;gy<currentMap.world.h-700&&specs.length<62;gy+=720){for(let gx=520;gx<currentMap.world.w-700&&specs.length<62;gx+=860){if(((gx/860+gy/720)|0)%3===0)continue;const spec={x:gx+((gy/720)|0)%2*130,y:gy,w:440+(((gx/860)|0)%3)*55,h:330+(((gy/720)|0)%3)*45,door:['bottom','right','top','left'][(((gx/860)|0)+((gy/720)|0))%4]};if(canBuild(spec,specs))specs.push(spec);}}
 currentMap.roads=currentMap.roads.concat(currentMap.localRoads);
 specs.forEach(addBuilding);
 const chestBuildings=shuffle(currentMap.buildings.length).map(function(i){return currentMap.buildings[i];}).filter(function(b){return !b.locked&&Math.hypot(b.x-currentMap.spawn.x,b.y-currentMap.spawn.y)>650;}).slice(0,18);
 chestBuildings.forEach(function(b){currentMap.chestPositions.push({x:b.x+b.w*.68,y:b.y+b.h*.53,buildingIndex:b.index});});
 function inRoad(x,y,m){m=m||0;return currentMap.roads.some(function(r){return x>r.x-m&&x<r.x+r.w+m&&y>r.y-m&&y<r.y+r.h+m;});}
 function inWater(x,y){return currentMap.waterZones.some(function(z){const dx=(x-z.x)/z.rx,dy=(y-z.y)/z.ry;return dx*dx+dy*dy<1.08;});}
 function inBuilding(x,y,m){m=m||0;return currentMap.buildings.some(function(b){return x>b.x-m&&x<b.x+b.w+m&&y>b.y-m&&y<b.y+b.h+m;});}
 // Cars on roads act as real collision cover.
 for(let i=0;i<58;i++){const r=randomFrom(currentMap.roads),horizontal=r.w>r.h,x=r.x+80+Math.random()*Math.max(80,r.w-160),y=r.y+70+Math.random()*Math.max(70,r.h-140),w=horizontal?110:54,h=horizontal?54:110;if(!inBuilding(x,y,120)){currentMap.vehicles.push({x:x,y:y,w:w,h:h,horizontal:horizontal,type:i%5});addWall(x-w/2,y-h/2,w,h,null,'prop');currentMap.enemyCandidates.push([x+150,y+150]);}}
 // Rocks, sandbags and concrete barriers fill open areas.
 for(let i=0;i<170;i++){const x=250+Math.random()*(currentMap.world.w-500),y=250+Math.random()*(currentMap.world.h-500);if(inWater(x,y)||inBuilding(x,y,160))continue;if(i<60){const rad=28+Math.random()*32;currentMap.rocks.push({x:x,y:y,r:rad});addWall(x-rad*.55,y-rad*.55,rad*1.1,rad*1.1,null,'prop');}else{const w=70+Math.random()*110,h=24+Math.random()*24;currentMap.coverProps.push({x:x,y:y,w:w,h:h,type:i%4});addWall(x-w/2,y-h/2,w,h,null,'prop');}}
 // Dense forest belts plus collidable tree trunks.
 for(let i=0;i<1500;i++){let x,y;if(i<520){const edge=i%4;if(edge===0){x=100+Math.random()*1900;y=Math.random()*currentMap.world.h;}else if(edge===1){x=currentMap.world.w-2000+Math.random()*1900;y=Math.random()*currentMap.world.h;}else if(edge===2){x=Math.random()*currentMap.world.w;y=100+Math.random()*1300;}else{x=Math.random()*currentMap.world.w;y=currentMap.world.h-1400+Math.random()*1300;}}else{x=250+Math.random()*(currentMap.world.w-500);y=250+Math.random()*(currentMap.world.h-500);}if(inRoad(x,y,55)||inWater(x,y)||inBuilding(x,y,115))continue;const rad=22+Math.random()*30;currentMap.bushes.push([x,y,rad]);if(currentMap.treeTrunks.length<230&&rad>37){currentMap.treeTrunks.push({x:x,y:y,r:10});addWall(x-10,y-10,20,20,null,'prop');}}
 for(let i=0;i<520;i++){const x=180+Math.random()*(currentMap.world.w-360),y=180+Math.random()*(currentMap.world.h-360);if(!inRoad(x,y,30)&&!inWater(x,y)&&!inBuilding(x,y,70))currentMap.grassPatches.push({x:x,y:y,scale:.65+Math.random()*.9,type:i%3});}
 currentMap.buildings.slice(0,34).forEach(function(b,index){const horizontal=b.doorSide==='top'||b.doorSide==='bottom',length=180+(index%4)*55;let x=b.x+b.w/2,y=b.y+b.h/2;if(b.doorSide==='bottom')y=b.y-76;else if(b.doorSide==='top')y=b.y+b.h+76;else if(b.doorSide==='left')x=b.x+b.w+76;else x=b.x-76;const w=horizontal?length:14,h=horizontal?14:length;if(!inWater(x,y)&&!inRoad(x,y,20)){currentMap.fences.push({x:x,y:y,w:w,h:h,horizontal:horizontal,type:index%2});addWall(x-w/2,y-h/2,w,h,null,'fence');}});
 currentMap.roads.forEach(function(r,roadIndex){const horizontal=r.w>r.h,length=horizontal?r.w:r.h;for(let offset=420;offset<length-300&&currentMap.streetLights.length<72;offset+=1150){const x=horizontal?r.x+offset:r.x+(roadIndex%2?r.w+38:-38),y=horizontal?r.y+(roadIndex%2?r.h+38:-38):r.y+offset;if(!inWater(x,y)&&!inBuilding(x,y,80))currentMap.streetLights.push({x:x,y:y,horizontal:horizontal,type:roadIndex%2});}});
 setExtractionActive(false);
};

function createEnemyGear(level,kind){
 const primary=randomGear('primary',level,level),secondary=randomGear('secondary',level,level);
 return{
  primary:primary||null,
  secondary:primary?null:(secondary||null),
  armor:kind==='normal'&&Math.random()<.22?null:randomGear('armor',level,level),
  helmet:kind==='normal'&&Math.random()<.48?null:randomGear('helmet',level,level),
  backpack:kind==='normal'&&Math.random()<.68?null:randomGear('backpack',level,level)
 };
}

placeEntitiesForMap=function(){const cfg=difficultyConfig[raidDifficulty],occ=[{x:currentMap.spawn.x,y:currentMap.spawn.y,r:220}];extractionPoints().forEach(function(e){occ.push({x:e.x+e.w/2,y:e.y+e.h/2,r:260});});
 crates=currentMap.chestPositions.slice(0,18).map(function(p){return{x:p.x,y:p.y,r:25,opened:false,loot:null,containsQuest:false,keyIds:[],rare:false,buildingIndex:p.buildingIndex};});
 const keys8=[];currentMap.lockedRooms.forEach(function(room){keys8.push(room.keyId,room.keyId);});shuffle(keys8.length).forEach(function(idx,i){crates[i%crates.length].keyIds.push(keys8[idx]);});shuffle(crates.length).slice(0,3).forEach(function(i){crates[i].containsQuest=true;});
 currentMap.lockedRooms.forEach(function(room){crates.push({x:room.crate.x,y:room.crate.y,r:30,opened:false,loot:null,containsQuest:false,keyIds:[],rare:true,roomId:room.id});});crates.forEach(function(c){occ.push({x:c.x,y:c.y,r:c.rare?65:52});});
 const total=cfg.normal+cfg.elite,positions=placeCandidates(currentMap.enemyCandidates,total,22,occ);
 enemies=positions.map(function(p,i){
  const elite=i>=cfg.normal,scale=cfg.enemyScale,level=elite?Math.min(5,cfg.lootMax+1):Math.max(1,cfg.lootMin+Math.floor(Math.random()*(cfg.lootMax-cfg.lootMin+1))),kind=elite?'elite':'normal';
  return{x:p.x,y:p.y,r:elite?22:18,hp:(elite?145:58)*scale,maxHp:(elite?145:58)*scale,angle:Math.random()*Math.PI*2,speed:elite?76:84,cooldown:Math.random(),alertTimer:0,patrolTimer:1+Math.random()*3,patrolAngle:Math.random()*Math.PI*2,strafe:i%2?1:-1,variant:i%3,kind:kind,vision:cfg.vision,gearLevel:level,gear:createEnemyGear(level,kind),dead:false};
 });
 const bossSpot=randomValid(30,occ.concat(enemies.map(function(e){return{x:e.x,y:e.y,r:80};})))||{x:currentMap.world.w*.55,y:currentMap.world.h*.55};const bossLevel=raidDifficulty==='A'?5:raidDifficulty==='B'?4:3;enemies.push({x:bossSpot.x,y:bossSpot.y,r:29,hp:430*cfg.enemyScale,maxHp:430*cfg.enemyScale,angle:0,speed:66,cooldown:0,alertTimer:0,patrolTimer:1,patrolAngle:0,strafe:1,variant:2,kind:'boss',vision:cfg.vision,gearLevel:bossLevel,gear:createEnemyGear(bossLevel,'boss'),dead:false});
};

function randomGear(category,min,max){const level=min+Math.floor(Math.random()*(max-min+1)),pool=gearPools[category][level]||[];return pool.length?randomFrom(pool):null;}
lootTable=function(){const cfg=difficultyConfig[raidDifficulty],common=[['food',11],['medicine',10],['tools',10],['battery',8],['optics',8],['militaryRadio',5],['goldChain',4],['cpu',4],['bandage',7],['medkit',5],['traumaKit',2],['ammoPack',7],['fragGrenade',4],['smokeGrenade',3],['flashGrenade',3],['redDot',2],['ammoPouch',1],['combatKnife',1]];if(raidDifficulty==='B')common.push(['graphicsCard',3],['antiqueWatch',5],['keycard',2],['thermalCore',1],['recoilGrip',2],['suppressor',1]);if(raidDifficulty==='A')common.push(['graphicsCard',6],['cryptoWallet',3],['prototypeChip',2],['thermalCore',4],['encryptedServer',2],['diamondCase',1],['extendedMag',2],['tacticalAmmoPouch',1],['fieldMachete',1]);return common;};
generateCrateLoot=function(crate){const cfg=difficultyConfig[raidDifficulty];if(crate.rare){const table=raidDifficulty==='A'?[['graphicsCard',18],['cryptoWallet',16],['prototypeChip',13],['diamondCase',9],['classifiedDocs',15],['thermalCore',14],['encryptedServer',10]]:raidDifficulty==='B'?[['graphicsCard',22],['cryptoWallet',8],['prototypeChip',4],['classifiedDocs',20],['thermalCore',12],['keycard',18]]:[['graphicsCard',14],['classifiedDocs',18],['keycard',25],['cpu',20],['goldChain',18]];const arr=[],count=3+Math.floor(Math.random()*3);for(let i=0;i<count;i++)arr.push(weightedPick(table));const gear=randomGear(Math.random()<.55?'primary':'armor',Math.max(1,cfg.lootMin),cfg.lootMax);if(gear)arr.push(gear);return arr;}
 const arr=[];if(crate.containsQuest)arr.push('questDrive');if(crate.keyIds)crate.keyIds.forEach(function(id){arr.push(id);});const count=2+Math.floor(Math.random()*3);for(let i=0;i<count;i++)arr.push(weightedPick(lootTable()));if(Math.random()<(.08+cfg.lootMax*.025)){const categories=['primary','secondary','armor','helmet','backpack'],g=randomGear(randomFrom(categories),cfg.lootMin,cfg.lootMax);if(g)arr.push(g);}return arr;};
