enemyShoot=function(e){const cfg=difficultyConfig[raidDifficulty],dist=Math.hypot(player.x-e.x,player.y-e.y),speed=e.kind==='boss'?760:e.kind==='elite'?700:650,leadTime=Math.min(.72,dist/speed),leadSkill=Math.max(.45,Math.min(1,1.35-(cfg.accuracyScale||1)*.45)),leadScale=(e.kind==='boss'?.9:e.kind==='elite'?.72:.58)*leadSkill,targetX=player.x+(player.vx||0)*leadTime*leadScale,targetY=player.y+(player.vy||0)*leadTime*leadScale,accuracy=(e.kind==='boss'?.025:e.kind==='elite'?.045:.085)*(cfg.accuracyScale||1),distanceSpread=Math.max(0,dist-300)/Math.max(500,cfg.vision||620)*accuracy*.38,a=Math.atan2(targetY-e.y,targetX-e.x)+(Math.random()-.5)*(accuracy+distanceSpread),base=e.kind==='boss'?22:e.kind==='elite'?16:10,weaponId=e.gear&&(e.gear.primary||e.gear.secondary),x=e.x+Math.cos(a)*30,y=e.y+Math.sin(a)*30;bullets.push({x:x,y:y,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed,r:3,life:2,owner:'enemy',damage:base*cfg.damageScale,weaponId:weaponId});e.cooldown=(e.kind==='boss'?.075:e.kind==='elite'?.11:.16)+Math.random()*(e.kind==='boss'?.045:e.kind==='elite'?.06:.08);createParticles(x,y,3,'muzzle');if(!isShotgunWeapon(weaponId))createMuzzleFlash(x,y,a,e.kind==='boss'?1.25:.85,'enemy');playTone(e.kind==='boss'?82:112,.035,'square',.018);};

