function buildStashLayout(){
 const level=currentStashLevel(),cells=Array(level.cols*level.rows).fill(false),placed=[],overflow=[];
 const units=[];
 Object.keys(meta.stash).filter(function(id){return itemDefs[id]&&stashCount(id)>0;}).forEach(function(id){for(let unit=0;unit<stashCount(id);unit++)units.push({id:id,unit:unit});});
 units.sort(function(a,b){const sa=itemGridSize(a.id,false),sb=itemGridSize(b.id,false);return sb.w*sb.h-sa.w*sa.h||(gearLevel(b.id)-gearLevel(a.id));});
 function spotFor(size){for(let y=0;y<=level.rows-size.h;y++)for(let x=0;x<=level.cols-size.w;x++){let clear=true;for(let yy=0;yy<size.h&&clear;yy++)for(let xx=0;xx<size.w;xx++)if(cells[(y+yy)*level.cols+x+xx]){clear=false;break;}if(clear)return{x:x,y:y,w:size.w,h:size.h};}return null;}
 units.forEach(function(unit){const normal=itemGridSize(unit.id,false),turned=itemGridSize(unit.id,true);let rotated=false,spot=spotFor(normal);if(!spot&&normal.w!==normal.h){spot=spotFor(turned);rotated=!!spot;}if(!spot){overflow.push(unit);return;}for(let yy=0;yy<spot.h;yy++)for(let xx=0;xx<spot.w;xx++)cells[(spot.y+yy)*level.cols+spot.x+xx]=true;placed.push(Object.assign({id:unit.id,unit:unit.unit,rotated:rotated},spot));});
 return{level:level,placed:placed,overflow:overflow};
}
